-- ═════════════════════════════════════════════════════════════════════════════
-- Hand-written below: rules Prisma's schema language cannot express.
-- Covered by apps/api/test/database.e2e-spec.ts and students-groups.e2e-spec.ts.
-- ═════════════════════════════════════════════════════════════════════════════

-- ── Normalized values ──────────────────────────────────────────────────────
ALTER TABLE "auth_challenges"
  ADD CONSTRAINT "auth_challenges_email_normalized" CHECK ("email" = lower(btrim("email")));
ALTER TABLE "student_profiles"
  ADD CONSTRAINT "student_profiles_phone_format" CHECK ("phone" IS NULL OR "phone" ~ '^\+?[0-9]{7,15}$');
ALTER TABLE "student_profiles"
  ADD CONSTRAINT "student_profiles_name_parts_present" CHECK (
    ("first_name" IS NULL OR btrim("first_name") <> '') AND
    ("father_name" IS NULL OR btrim("father_name") <> '') AND
    ("grandfather_name" IS NULL OR btrim("grandfather_name") <> '') AND
    ("family_name" IS NULL OR btrim("family_name") <> ''));

-- ── Name search key (§18.1: Arabic names are searched however they are spelled) ──
-- Mirrors `nameMatchKey` in @ftms/core for letters: removes diacritics and
-- tatweel, unifies alef/hamza forms, alef maqsura, taa marbuta, waw/yaa with
-- hamza, converts Arabic-Indic digits, and drops spacing and punctuation.
CREATE FUNCTION "ftms_name_key"(value TEXT) RETURNS TEXT
LANGUAGE sql IMMUTABLE PARALLEL SAFE RETURNS NULL ON NULL INPUT AS $$
  SELECT left(
    regexp_replace(
      translate(
        regexp_replace(lower(normalize(value, NFKC)), U&'[\064B-\065F\0670\06D6-\06ED\0640]', '', 'g'),
        U&'\0622\0623\0625\0671\0672\0673\0649\0629\0624\0626\0660\0661\0662\0663\0664\0665\0666\0667\0668\0669\06F0\06F1\06F2\06F3\06F4\06F5\06F6\06F7\06F8\06F9',
        U&'\0627\0627\0627\0627\0627\0627\064A\0647\0648\064A' || '01234567890123456789'),
      U&'[\0020\0009\000A\000D\00A0\060C\061B\061F\06D4' || '.,;:!?''"()_/-]', '', 'g'),
    200)
$$;

CREATE FUNCTION "ftms_student_name_key"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW."name_key" := "ftms_name_key"(NEW."full_name");
  RETURN NEW;
END $$;

CREATE TRIGGER "student_profiles_name_key"
  BEFORE INSERT OR UPDATE OF "full_name", "name_key" ON "student_profiles"
  FOR EACH ROW EXECUTE FUNCTION "ftms_student_name_key"();

UPDATE "student_profiles" SET "name_key" = "ftms_name_key"("full_name");

-- ── Accounts: only students can wait for verification, and an ACTIVE student
--    account must be linked to a student record (§4.2 Case B: no access to
--    academic data before verification). Deferred, so an account and its link
--    can be created or changed together inside one transaction.
ALTER TABLE "users"
  ADD CONSTRAINT "users_pending_only_students" CHECK ("status" <> 'PENDING_VERIFICATION' OR "role" = 'STUDENT');

CREATE FUNCTION "ftms_check_active_student_linked"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  account UUID;
BEGIN
  IF TG_TABLE_NAME = 'users' THEN
    account := NEW."id";
  ELSE
    account := OLD."user_id"; -- the account a student record was linked to before
  END IF;
  IF account IS NULL THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM "users" u WHERE u."id" = account AND u."role" = 'STUDENT' AND u."status" = 'ACTIVE')
     AND NOT EXISTS (SELECT 1 FROM "student_profiles" p WHERE p."user_id" = account) THEN
    RAISE EXCEPTION 'active student account % must be linked to a student record', account
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER "users_active_student_linked"
  AFTER INSERT OR UPDATE OF "status", "role" ON "users"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_active_student_linked"();
CREATE CONSTRAINT TRIGGER "student_profiles_active_link_kept"
  AFTER UPDATE OF "user_id" OR DELETE ON "student_profiles"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_active_student_linked"();

-- ── Training groups (§5) ───────────────────────────────────────────────────
ALTER TABLE "training_groups"
  ADD CONSTRAINT "training_groups_name_tidy" CHECK ("name" = btrim("name") AND "name" <> '');
-- Unique ignoring case and repeated spaces ("Group  A" = "group a").
CREATE UNIQUE INDEX "training_groups_name_key"
  ON "training_groups" (lower(regexp_replace("name", '\s+', ' ', 'g')));

-- ── Group memberships: ONE active group per student, enforced here (§5, §16.1) ──
CREATE UNIQUE INDEX "group_memberships_one_active_per_student"
  ON "group_memberships" ("student_id") WHERE "ended_at" IS NULL;
ALTER TABLE "group_memberships"
  ADD CONSTRAINT "group_memberships_end_after_start" CHECK ("ended_at" IS NULL OR "ended_at" >= "started_at");

-- New memberships only in non-archived groups; history (ended rows) is immutable;
-- an active row may only be ended. The group row is share-locked so archiving and
-- joining the same group cannot race past each other.
CREATE FUNCTION "ftms_check_membership"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  group_archived TIMESTAMPTZ(3);
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT "archived_at" INTO group_archived FROM "training_groups" WHERE "id" = NEW."group_id" FOR SHARE;
    IF NEW."ended_at" IS NULL AND group_archived IS NOT NULL THEN
      RAISE EXCEPTION 'group % is archived and accepts no members', NEW."group_id"
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW."student_id" <> OLD."student_id" OR NEW."group_id" <> OLD."group_id"
     OR NEW."source" <> OLD."source" OR NEW."started_at" <> OLD."started_at" THEN
    RAISE EXCEPTION 'membership % cannot be reassigned; end it and start a new one', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."ended_at" IS NOT NULL THEN
    -- Only foreign-key SET NULL of the actor columns may touch an ended row.
    IF NEW."ended_at" IS DISTINCT FROM OLD."ended_at"
       OR (NEW."assigned_by_id" IS DISTINCT FROM OLD."assigned_by_id" AND NEW."assigned_by_id" IS NOT NULL)
       OR (NEW."ended_by_id" IS DISTINCT FROM OLD."ended_by_id" AND NEW."ended_by_id" IS NOT NULL) THEN
      RAISE EXCEPTION 'membership % has ended and is part of the history', OLD."id"
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "group_memberships_check"
  BEFORE INSERT OR UPDATE ON "group_memberships"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_membership"();

CREATE FUNCTION "ftms_check_group_archive"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."archived_at" IS NOT NULL AND OLD."archived_at" IS NULL
     AND EXISTS (SELECT 1 FROM "group_memberships" m WHERE m."group_id" = NEW."id" AND m."ended_at" IS NULL) THEN
    RAISE EXCEPTION 'group % still has members', NEW."id" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "training_groups_archive_check"
  BEFORE UPDATE OF "archived_at" ON "training_groups"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_group_archive"();

-- ── Imports ────────────────────────────────────────────────────────────────
ALTER TABLE "student_imports"
  ADD CONSTRAINT "student_imports_state" CHECK (
    ("status" = 'PREVIEW' AND "committed_at" IS NULL AND "discarded_at" IS NULL) OR
    ("status" = 'COMMITTED' AND "committed_at" IS NOT NULL AND "discarded_at" IS NULL) OR
    ("status" = 'DISCARDED' AND "discarded_at" IS NOT NULL AND "committed_at" IS NULL));
ALTER TABLE "student_imports"
  ADD CONSTRAINT "student_imports_file" CHECK ("file_size" > 0 AND "file_sha256" ~ '^[0-9a-f]{64}$');
ALTER TABLE "student_imports"
  ADD CONSTRAINT "student_imports_rows_array" CHECK (jsonb_typeof("rows") = 'array');

-- ── Review requests: one open request at a time; decisions are complete ─────
CREATE UNIQUE INDEX "student_verification_requests_one_pending"
  ON "student_verification_requests" ("user_id") WHERE "status" = 'PENDING';
ALTER TABLE "student_verification_requests"
  ADD CONSTRAINT "student_verification_requests_decision" CHECK (
    ("status" = 'PENDING') = ("decided_at" IS NULL) AND
    ("status" <> 'REJECTED' OR "decision_reason" IS NOT NULL) AND
    ("status" <> 'APPROVED' OR "student_id" IS NOT NULL));
ALTER TABLE "student_verification_requests"
  ADD CONSTRAINT "student_verification_requests_seat_format" CHECK ("seat_number" ~ '^[A-Z0-9-]{1,20}$');

CREATE FUNCTION "ftms_check_verification_account"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (SELECT "role" FROM "users" WHERE "id" = NEW."user_id") <> 'STUDENT' THEN
    RAISE EXCEPTION 'verification requests are for student accounts only'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "student_verification_requests_account_check"
  BEFORE INSERT OR UPDATE OF "user_id" ON "student_verification_requests"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_verification_account"();

CREATE UNIQUE INDEX "profile_change_requests_one_pending"
  ON "profile_change_requests" ("student_id") WHERE "status" = 'PENDING';
ALTER TABLE "profile_change_requests"
  ADD CONSTRAINT "profile_change_requests_decision" CHECK (
    ("status" = 'PENDING') = ("decided_at" IS NULL) AND
    ("status" <> 'REJECTED' OR "decision_reason" IS NOT NULL));
ALTER TABLE "profile_change_requests"
  ADD CONSTRAINT "profile_change_requests_payload" CHECK (
    jsonb_typeof("current") = 'object' AND jsonb_typeof("proposed") = 'object' AND "proposed" <> '{}'::jsonb);

-- ── Row Level Security (Supabase Data API gets nothing; see Phase 1) ────────
ALTER TABLE "training_groups" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "group_memberships" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "student_imports" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "student_verification_requests" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "profile_change_requests" ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
  api_role TEXT;
BEGIN
  FOREACH api_role IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = api_role) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', api_role);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', api_role);
    END IF;
  END LOOP;
END $$;
